const raw = $input.first().json;
const requestId = $('Set — Extract & Propagate Context').first().json.request_id;
const campaignId = $('Set — Flatten Campaign Record').first().json.campaign_id;

// Anthropic returns content[0].text
let brandResult;
try {
  const text = raw.content?.[0]?.text ?? raw.text ?? '';
  brandResult = JSON.parse(text.trim());
} catch (e) {
  brandResult = { score: 0, flags: ['parse_error'], pass: false, summary: 'Failed to parse brand check response: ' + e.message };
}

return [{
  json: {
    request_id: requestId,
    campaign_id: campaignId,
    campaign_name: $('Set — Flatten Campaign Record').first().json.campaign_name,
    campaign_goal: $('Set — Flatten Campaign Record').first().json.campaign_goal,
    campaign_offer: $('Set — Flatten Campaign Record').first().json.campaign_offer,
    campaign_persona: $('Set — Flatten Campaign Record').first().json.campaign_persona,
    brand_score: brandResult.score ?? 0,
    brand_flags: brandResult.flags ?? [],
    brand_pass: brandResult.pass ?? false,
    brand_summary: brandResult.summary ?? ''
  }
}];

