const raw = $input.first().json;
const upstream = $('Code — Parse Brand Check Result').first().json;

let adResult;
try {
  const text = raw.content?.[0]?.text ?? raw.text ?? '';
  adResult = JSON.parse(text.trim());
} catch (e) {
  throw new Error('Ad variant parse failed: ' + e.message);
}

if (!adResult.variants || !Array.isArray(adResult.variants)) {
  throw new Error('Ad variant response missing .variants array');
}

// Emit one item per variant, all carrying request_id and campaign context
return adResult.variants.map((v, idx) => ({
  json: {
    request_id: upstream.request_id,
    campaign_id: upstream.campaign_id,
    campaign_name: upstream.campaign_name,
    campaign_goal: upstream.campaign_goal,
    campaign_offer: upstream.campaign_offer,
    campaign_persona: upstream.campaign_persona,
    brand_summary: upstream.brand_summary,
    variant_index: idx,
    variant_tag: v.variant_tag ?? `v${idx + 1}_${v.platform}`,
    platform: v.platform,
    headline: v.headline,
    body_copy: v.body_copy,
    cta_label: v.cta_label,
    angle: v.angle
  }
}));

