// Inline LP config validation (mirrors @me/lp-config Zod schema).
// n8n Code nodes cannot import workspace packages, so we replicate the rules.

const raw = $input.all();
const results = [];

for (const item of raw) {
  const upstream = item.json;
  let config;

  // Parse Anthropic response
  try {
    const text = upstream.content?.[0]?.text ?? upstream.text ?? '';
    // Strip possible markdown fences
    const cleaned = text.trim().replace(/^```json\s*/i, '').replace(/^```\s*/i, '').replace(/\s*```$/i, '');
    config = JSON.parse(cleaned);
  } catch (e) {
    throw new Error(`LP config parse error for variant ${upstream.variant_tag}: ${e.message}`);
  }

  // --- Validation rules (mirrors Zod schema) ---
  const errors = [];

  if (typeof config.slug !== 'string' || config.slug.length < 3 || config.slug.length > 64 || !/^[a-z0-9-]+$/.test(config.slug)) {
    errors.push('slug: must be 3-64 chars, lowercase/digits/hyphens only');
  }

  const validTemplates = ['template_a_lead_capture', 'template_b_long_form'];
  if (!validTemplates.includes(config.template)) {
    errors.push(`template: must be one of ${validTemplates.join(', ')}`);
  }

  if (!config.theme || typeof config.theme.primary !== 'string' || typeof config.theme.background !== 'string' || typeof config.theme.text !== 'string') {
    errors.push('theme: primary, background, text are required strings');
  }

  if (!config.hero || typeof config.hero.headline !== 'string' || config.hero.headline.length < 1 || config.hero.headline.length > 140) {
    errors.push('hero.headline: required string, max 140 chars');
  }

  if (!Array.isArray(config.bullets) || config.bullets.length > 6) {
    errors.push('bullets: must be array max 6 items');
  }

  if (!config.form || !Array.isArray(config.form.fields) || config.form.fields.length < 1 || config.form.fields.length > 8) {
    errors.push('form.fields: must be array 1-8 items');
  } else {
    const validFieldTypes = ['email', 'text', 'tel', 'textarea', 'select', 'checkbox'];
    config.form.fields.forEach((f, i) => {
      if (!f.name || typeof f.name !== 'string') errors.push(`form.fields[${i}].name: required`);
      if (!f.label || typeof f.label !== 'string') errors.push(`form.fields[${i}].label: required`);
      if (!validFieldTypes.includes(f.type)) errors.push(`form.fields[${i}].type: invalid`);
    });
  }

  if (!config.form?.submit_label) errors.push('form.submit_label: required');
  if (!config.form?.success_message) errors.push('form.success_message: required');

  if (!config.tracking || typeof config.tracking.campaign_id !== 'string') {
    errors.push('tracking.campaign_id: required uuid string');
  }

  if (errors.length > 0) {
    throw new Error(`LP config validation failed for variant ${upstream.variant_tag}: ${errors.join('; ')}`);
  }

  // Force status=draft and ensure version=1
  config.status = 'draft';
  config.version = config.version ?? 1;
  config.pixels = config.pixels ?? {};

  results.push({
    json: {
      request_id: upstream.request_id,
      campaign_id: upstream.campaign_id,
      variant_tag: upstream.variant_tag,
      platform: upstream.platform,
      headline: upstream.headline,
      body_copy: upstream.body_copy,
      cta_label: upstream.cta_label,
      angle: upstream.angle,
      lp_config: config,
      lp_slug: config.slug
    }
  });
}

return results;

// Aggregate all variant results into one summary for the final PATCH to Twenty.
const items = $input.all();
const requestId = items[0]?.json?.request_id ?? 'unknown';
const campaignId = items[0]?.json?.campaign_id ?? 'unknown';

const slugs = items.map(i => i.json.lp_slug).filter(Boolean);
const platforms = [...new Set(items.map(i => i.json.platform))];
const variantCount = items.length;

return [{
  json: {
    request_id: requestId,
    campaign_id: campaignId,
    variant_count: variantCount,
    slugs: slugs,
    platforms: platforms,
    success: true
  }
}];
